<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Tagore Fee Management</title><style>body{font-family:system-ui,sans-serif;background:#f5f7fa;color:#17202a;margin:0}.wrap{max-width:1250px;margin:28px auto;padding:0 18px}.card{background:#fff;border:1px solid #e5e7eb;border-radius:14px;padding:20px;margin-bottom:18px}.grid{display:grid;grid-template-columns:repeat(4,1fr);gap:12px}.head{display:grid;grid-template-columns:2fr 1fr 1fr 1fr auto;gap:8px;align-items:end;margin-bottom:8px}.field label{display:block;font-size:12px;color:#64748b;margin-bottom:4px}.field input,.field select{width:100%;box-sizing:border-box;padding:9px;border:1px solid #cbd5e1;border-radius:8px}.btn{border:0;border-radius:8px;padding:10px 14px;cursor:pointer}.primary{background:#111827;color:#fff}.success{background:#166534;color:#fff}.muted{color:#64748b}.table{width:100%;border-collapse:collapse}.table th,.table td{padding:9px;border-bottom:1px solid #eee;text-align:left;font-size:14px}.right{text-align:right}.notice{padding:10px 14px;background:#ecfdf5;border:1px solid #bbf7d0;border-radius:8px;margin-bottom:16px}@media(max-width:850px){.grid,.head{grid-template-columns:1fr 1fr}.card{overflow:auto}}</style></head><body><div class="wrap">
